import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DyLyN3RJ.js";const d=JSON.parse('{"title":"2026-11-05 Agent 核心研究与竞品动态","description":"企业化治理、协作契约与真实交付；31 组事实观察、6 组研究分析，保留版本与验证边界。","frontmatter":{"title":"2026-11-05 Agent 核心研究与竞品动态","description":"企业化治理、协作契约与真实交付；31 组事实观察、6 组研究分析，保留版本与验证边界。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-05.md","filePath":"zh/runtime/daily-intelligence/2026-11-05.md","lastUpdated":1793864474000}'),n={name:"zh/runtime/daily-intelligence/2026-11-05.md"};function l(i,e,p,s,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-11-05-agent-核心研究与竞品动态" tabindex="-1">2026-11-05 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-05-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-05 Agent 核心研究与竞品动态&quot;">​</a></h1><p><strong>核心结论：今天最值得学习的是“当前授权、协作投递、独立交付凭据”如何贯穿数字员工的持续履职。</strong> AG2 1.3 和 LangGraph 1.2.20 提供已发行的协作/恢复机制；Paperclip 的真实交付检查值得研究；Paradev 转为 MIT 是本轮最明确的竞品判断更新。OpenAI 原生 worker 合入预览分支，仍须与稳定产品和未合入存储/审计提案分开。</p><p>采用已确认的两层交付：<strong>31 组事实观察 O1–O31 → 6 组研究分析 A1–A6</strong>；另有历史协议候选 C1，不计新增。实际执行起点 <strong>2026-11-05 13:43:53 Asia/Shanghai（05:43:53 UTC）</strong>，常规提交筛选承接昨日成功基线 <strong>2026-11-04 08:42:35 UTC</strong>；Orca/TSA 等历史空档按来源保留，PR 状态采用当轮回读时的最新状态，起点后变化单独注明。对照昨日公开日档和本地事件记录去重，发行/合入状态升级不冒充新发明。</p><h2 id="第一层-事实观察" tabindex="-1">第一层：事实观察 <a class="header-anchor" href="#第一层-事实观察" aria-label="Permalink to &quot;第一层：事实观察&quot;">​</a></h2><p>所有测试数字、实测和故障描述如未另注均为上游作者的公开证据；本轮未安装、复现或运行这些产品。MERGED 不自动等于已发行；OPEN/DRAFT 不视为现有产品能力。</p><h3 id="o1-ag2-1-3-正式发行-协作事件、状态作用域和任务生命周期" tabindex="-1">O1. AG2 1.3 正式发行：协作事件、状态作用域和任务生命周期 <a class="header-anchor" href="#o1-ag2-1-3-正式发行-协作事件、状态作用域和任务生命周期" aria-label="Permalink to &quot;O1. AG2 1.3 正式发行：协作事件、状态作用域和任务生命周期&quot;">​</a></h3><p><strong>v1.3.0 RELEASED stable · 2026-11-04 09:21 UTC</strong></p><p>祖先可观察所有后代的 ChildEvent 和原始用量事件；观察不会进入父模型对话或触发父工具/HITL，成本按来源事件去重。COPIED、LOCAL、SHARED 明确跨委派边界，SHARED 的并发同步由应用负责。TTL 是给外部观察者的期限，不是本地执行超时。昨天的合入线索现升级为正式发行；要求 Python ≥3.11，TaskConfig 等入口计划在 1.4 移除，迁移有成本。</p><p>原始来源：<a href="https://github.com/ag2ai/ag2/releases/tag/v1.3.0" target="_blank" rel="noreferrer">1</a></p><h3 id="o2-langgraph-1-2-20-过期审批答复可拒绝-每次-interrupt-独立编号" tabindex="-1">O2. LangGraph 1.2.20：过期审批答复可拒绝，每次 interrupt 独立编号 <a class="header-anchor" href="#o2-langgraph-1-2-20-过期审批答复可拒绝-每次-interrupt-独立编号" aria-label="Permalink to &quot;O2. LangGraph 1.2.20：过期审批答复可拒绝，每次 interrupt 独立编号&quot;">​</a></h3><p><strong>1.2.20 RELEASED stable · 2026-11-05 02:20 UTC; #9574/#9589 MERGED</strong></p><p>严格模式在写入前拒绝已不待处理的 interrupt ID、空回答映射和多问题下的歧义单值；第二次 interrupt 有自己的 ID，避免重试旧答复误答下一题。默认行为不变；使用私有配置键，RemoteGraph 不转发该键，过时 checkpoint 和嵌套图有检查例外，旧 ID 兼容回退仍保留。适合研究审批与问题版本绑定，不能据此声称所有恢复路径均拒绝旧答复。SDK 0.4.13 同时发行 cancel_reason 与状态字段选择。</p><p>原始来源：<a href="https://github.com/langchain-ai/langgraph/releases/tag/1.2.20" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9574" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9589" target="_blank" rel="noreferrer">3</a></p><h3 id="o3-openai-原生-worker-监督与不确定副作用恢复已合入预览分支" tabindex="-1">O3. OpenAI 原生 worker：监督与不确定副作用恢复已合入预览分支 <a class="header-anchor" href="#o3-openai-原生-worker-监督与不确定副作用恢复已合入预览分支" aria-label="Permalink to &quot;O3. OpenAI 原生 worker：监督与不确定副作用恢复已合入预览分支&quot;">​</a></h3><p><strong>Python #5499/#5501/#5502 and JS #2122/#2123/#2124 MERGED into feat/codex-harness · Nov 4–5; Python #5494 CLOSED NOT MERGED; #5514 OPEN</strong></p><p>支持指定 turn 的 steering、隔离写目录、等待子进程退出，以及外部副作用已发生但结果未落盘时先阻止恢复，由应用独立核实 applied/not_applied 后绑定原调用、刷盘并回读。JS 双 worker 示例在单独发布前核对完整文档和同 turn 执行哈希。合并的不是稳定 main，也未核实新发行包包含这些层；冷启动后代恢复、跨新 call ID 去重和通用 exactly-once 仍不提供。新 #5514 提议 SessionStore/SQLite 持久化、writer fencing 和未知结果阻断，仍 OPEN；其参考适配器限 POSIX，不能当 Windows 已验收。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/5502" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/openai-agents-python/pull/5494" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/openai/openai-agents-python/pull/5514" target="_blank" rel="noreferrer">3</a> · <a href="https://github.com/openai/openai-agents-js/pull/2124" target="_blank" rel="noreferrer">4</a></p><h3 id="o4-openai-原生-tracing-跨排队-子-turn-的上下文与隐私约束" tabindex="-1">O4. OpenAI 原生 tracing：跨排队/子 turn 的上下文与隐私约束 <a class="header-anchor" href="#o4-openai-原生-tracing-跨排队-子-turn-的上下文与隐私约束" aria-label="Permalink to &quot;O4. OpenAI 原生 tracing：跨排队/子 turn 的上下文与隐私约束&quot;">​</a></h3><p><strong>Python #5513/#5519 OPEN; JS #2155 OPEN · created Nov 4–5</strong></p><p>workflow/custom span 提案在排队准入前捕获上下文，延迟子工作保留父身份和更严格内容策略；processor 失败记录丢失但不改 Agent 结果，凭据不写入会话。被动 request metadata 提案只观察请求设置和保留响应，事件短暂且 best-effort，不赋予执行权限，暂不覆盖原生子调用、reviewer 或压缩请求。均未合入；自动跨进程传播和 trace viewer 交付等仍延期，上游 loopback 测试不等于真实后端验收。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/5513" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/openai-agents-js/pull/2155" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/openai/openai-agents-python/pull/5519" target="_blank" rel="noreferrer">3</a></p><h3 id="o5-openai-原生-a2a-适配器-任务状态与私有状态共同持久化" tabindex="-1">O5. OpenAI 原生 A2A 适配器：任务状态与私有状态共同持久化 <a class="header-anchor" href="#o5-openai-原生-a2a-适配器-任务状态与私有状态共同持久化" aria-label="Permalink to &quot;O5. OpenAI 原生 A2A 适配器：任务状态与私有状态共同持久化&quot;">​</a></h3><p><strong>JS #2129 MERGED into feat/codex-harness · 2026-11-05 05:46 UTC (post-start status recheck)</strong></p><p>可选 A2A 1.0 JSON-RPC 适配层采用官方 SDK peer，调用前核路由、取凭据前核端点、返回前核所有权。人工输入绑定 task/context/challenge/generation；恢复重发已保存 Task 投影而不重跑 Agent，丢失 mutation 回执保留 unknown。主机仍负责可信端点、当前授权、持久化和 mutation reservation，部署互操作未验收。本条状态在执行起点后复核更新为 MERGED；不是 A2A 已覆盖企业治理，也不是 FCoP 同层替代。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-js/pull/2129" target="_blank" rel="noreferrer">1</a></p><h3 id="o6-codex-权限按实际执行环境和调用边界解析" tabindex="-1">O6. Codex：权限按实际执行环境和调用边界解析 <a class="header-anchor" href="#o6-codex-权限按实际执行环境和调用边界解析" aria-label="Permalink to &quot;O6. Codex：权限按实际执行环境和调用边界解析&quot;">​</a></h3><p><strong>#59489/#59530/#59507/#59572 MERGED main · Nov 4–5; stable-release inclusion unverified</strong></p><p>MCP Guardian 使用工具所属环境的权限，早期评分与当前 owner 权限不符就重新审查。sandbox 启动时解析实际 workspace roots，空列表不给工作区访问并保留 deny；Windows 使用共同转换路径。记忆整理 Agent 仅能写记忆根、无网络；后台请求使用 runtime identity、每次请求取环境凭据并阻止云请求重定向。价值在于主体/环境/动作绑定，而非只看会话开始时的一次授权。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/59489" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/codex/pull/59530" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/openai/codex/pull/59507" target="_blank" rel="noreferrer">3</a> · <a href="https://github.com/openai/codex/pull/59572" target="_blank" rel="noreferrer">4</a></p><h3 id="o7-codex-压缩摘要不等于消息已被模型读取" tabindex="-1">O7. Codex：压缩摘要不等于消息已被模型读取 <a class="header-anchor" href="#o7-codex-压缩摘要不等于消息已被模型读取" aria-label="Permalink to &quot;O7. Codex：压缩摘要不等于消息已被模型读取&quot;">​</a></h3><p><strong>#59404 MERGED main · 2026-11-04 13:03 UTC</strong></p><p>保存 history sequence 和正常推理的采样 checkpoint，在本地/远程压缩、替换历史和 resume 后保留尚未被正常模型请求包含的 Agent 消息。摘要输出本身不能作为投递成功凭据；仍受既有大小预算约束。它把“已进入记录”和“已被下一次决策看到”分开，对多 Agent 交接尤其有研究价值，稳定发行包含情况未核实。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/59404" target="_blank" rel="noreferrer">1</a></p><h3 id="o8-adk-有界并行、待人工输入的委派和子-runner-清理" tabindex="-1">O8. ADK：有界并行、待人工输入的委派和子 runner 清理 <a class="header-anchor" href="#o8-adk-有界并行、待人工输入的委派和子-runner-清理" aria-label="Permalink to &quot;O8. ADK：有界并行、待人工输入的委派和子 runner 清理&quot;">​</a></h3><p><strong>main commits 5e4f0e18/60128104/73cfd62e · 2026-11-04; release inclusion unverified</strong></p><p>max_parallel_workers 可限制 workflow 并行 worker；默认 None 仍无限制，非法组合拒绝。single_turn 子 Agent 的 workflow 工具等待 RequestInput 时，委派继续 pending，避免提前给父方 None 并丢失后续回答；AgentTool 用 finally 关闭子 runner，异常和取消也清理工具资源。上游改动提供可研究机制，未在本地复现或验收。</p><p>原始来源：<a href="https://github.com/google/adk-python/commit/5e4f0e18cfe869a183901192f92c86d7574881b0" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google/adk-python/commit/601281049557d90d6406452716eb9f7de23b0dd5" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/google/adk-python/commit/73cfd62ed96747e8358cb19c299ae06791894e51" target="_blank" rel="noreferrer">3</a></p><h3 id="o9-adk-共享-app-user-状态并发写入与零值资源限制" tabindex="-1">O9. ADK：共享 app/user 状态并发写入与零值资源限制 <a class="header-anchor" href="#o9-adk-共享-app-user-状态并发写入与零值资源限制" aria-label="Permalink to &quot;O9. ADK：共享 app/user 状态并发写入与零值资源限制&quot;">​</a></h3><p><strong>main commits 6b2d4552/a702e3c0 · Nov 4–5</strong></p><p>数据库会话服务对共享 app/user 状态做进程内串行写入，创建会话时在 PostgreSQL/MySQL 锁定已有行；Redis 使用 watched transaction 合并，防止并行会话覆盖彼此键。不要将“进程内锁”泛化成全分布式保证。BashToolPolicy 的内存、文件大小和子进程上限 0 现在确实传给 setrlimit，None 才表示无上限。均为 main 代码，未核实发行。</p><p>原始来源：<a href="https://github.com/google/adk-python/commit/6b2d45523b06fd2e5a8ba5f52c2270f93d1607a4" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google/adk-python/commit/a702e3c083c893794e78ac15d6dc044798905326" target="_blank" rel="noreferrer">2</a></p><h3 id="o10-adk-a2a-集成移除-experimental-标记-恢复与撤权语义补齐" tabindex="-1">O10. ADK：A2A 集成移除 experimental 标记，恢复与撤权语义补齐 <a class="header-anchor" href="#o10-adk-a2a-集成移除-experimental-标记-恢复与撤权语义补齐" aria-label="Permalink to &quot;O10. ADK：A2A 集成移除 experimental 标记，恢复与撤权语义补齐&quot;">​</a></h3><p><strong>main commits 95d4a566/512d56b2/70e1cbde/02db0ff2 · Nov 4–5</strong></p><p>RemoteA2aAgent 等 API 移除实验警告；A2A task 不再因中途一次错误就永久 FAILED，同一/上级分支最终成功可消解相应错误，根错误例外。OAuth refresh 收到 invalid_grant 时删除死凭据并要求重授权；其他刷新故障仍可能保留旧 token。Live API 暂不可恢复更新不再抹掉最后有效 handle。移除标记并不证明跨部署互操作、所有凭据服务或长期运行均已验收。</p><p>原始来源：<a href="https://github.com/google/adk-python/commit/95d4a5660f5ab4707b251c0b7c86053e5c6f311e" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google/adk-python/commit/512d56b2220b08feda559787045a7d8c9f8ebe0f" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/google/adk-python/commit/70e1cbde75314f8a7a231a064b17754794baaa87" target="_blank" rel="noreferrer">3</a> · <a href="https://github.com/google/adk-python/commit/02db0ff256d9889b4a3a730bcaf5b63275b7ecc7" target="_blank" rel="noreferrer">4</a></p><h3 id="o11-adk-评测不能把不完整轨迹当作可验收输入" tabindex="-1">O11. ADK：评测不能把不完整轨迹当作可验收输入 <a class="header-anchor" href="#o11-adk-评测不能把不完整轨迹当作可验收输入" aria-label="Permalink to &quot;O11. ADK：评测不能把不完整轨迹当作可验收输入&quot;">​</a></h3><p><strong>main commits e4f6c3a9/16898f30/10b71623 · Nov 4–5</strong></p><p>每次 judge 响应使用该 invocation 自己的 rubric，防止多轮中错用最后一轮指标、漏掉失败项却给出通过。截断 payload 使 eval_ready=false，禁止投影掉能揭示截断的保护字段。TOOL_ERROR 补成错误响应；人工确认/输入/凭据工具保留在轨迹，但不计作业务工具循环。这是验收证据完整性修正，不是本地已完成 benchmark。</p><p>原始来源：<a href="https://github.com/google/adk-python/commit/e4f6c3a9c8fc8683a7493b62f0e8af5e04b396e4" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google/adk-python/commit/16898f30c9a5c6b2ae1ecf099424afff8fd28e77" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/google/adk-python/commit/10b716235500c12bb439fd10e57267da1e7d0dad" target="_blank" rel="noreferrer">3</a></p><h3 id="o12-mcp-apps-规范约束安全属性-允许单层或双层-iframe" tabindex="-1">O12. MCP Apps：规范约束安全属性，允许单层或双层 iframe <a class="header-anchor" href="#o12-mcp-apps-规范约束安全属性-允许单层或双层-iframe" aria-label="Permalink to &quot;O12. MCP Apps：规范约束安全属性，允许单层或双层 iframe&quot;">​</a></h3><p><strong>#717 MERGED · 2026-11-04 18:07 UTC; draft spec source verified</strong></p><p>不再强制双层 sandbox iframe，但网页宿主仍须跨源 iframe、规定 sandbox flags、等待 initialized，并由宿主控制的服务器以 HTTP headers 设置 CSP；不能直接把最敏感的安全属性交给第三方 MCP 服务器。单层和双层做法成为非规范性示例。作者计划用于 Gemini，不能当已部署证明；这次仅规范修改，作者注明截图/PDF 测试环境未全通过。</p><p>原始来源：<a href="https://github.com/modelcontextprotocol/ext-apps/pull/717" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/modelcontextprotocol/ext-apps/blob/main/specification/draft/apps.mdx" target="_blank" rel="noreferrer">2</a></p><h3 id="o13-paperclip-没有交付物凭据-不能仅凭最终文本关闭任务" tabindex="-1">O13. Paperclip：没有交付物凭据，不能仅凭最终文本关闭任务 <a class="header-anchor" href="#o13-paperclip-没有交付物凭据-不能仅凭最终文本关闭任务" aria-label="Permalink to &quot;O13. Paperclip：没有交付物凭据，不能仅凭最终文本关闭任务&quot;">​</a></h3><p><strong>#19130 MERGED master · 2026-11-05 03:46 UTC; release inclusion unverified</strong></p><p>上游复现：provider 最终文本声称有 Markdown 简报，但没有保存的文档/附件，合成 success 仍可把任务置 done。修复在 finalization 和状态提交事务再次查有效发布凭据；凭据被删、锁定或请求修订时重新判断，缺失输出只走有界修复。免文档降级必须有针对当前不变请求的真实人工拒绝，模型文字和旧决定均不足。上游有真实 PostgreSQL 对照，本地未复现。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；提高交付验收机制关注度，正式发行与生产资格判断暂不升级。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/19130" target="_blank" rel="noreferrer">1</a></p><h3 id="o14-paperclip-恢复文件、交接所有权和完成任务是三种不同权限" tabindex="-1">O14. Paperclip：恢复文件、交接所有权和完成任务是三种不同权限 <a class="header-anchor" href="#o14-paperclip-恢复文件、交接所有权和完成任务是三种不同权限" aria-label="Permalink to &quot;O14. Paperclip：恢复文件、交接所有权和完成任务是三种不同权限&quot;">​</a></h3><p><strong>#19181/#19184/#19038 MERGED master · Nov 4–5; #19186 OPEN at recheck</strong></p><p>失败的文件保留重启不能提前丢掉旧 stop receipt，磁盘满时可结束恢复、在新隔离工作区继续并保留旧源。新负责人仅在绑定的文件恢复凭据满足后解除 hold；旧负责人自己的 no-replay hold 仍保留，只有 snapshot 不足。旧 controller 的加密归档仅保存证据，不赋予执行权。另 #19186 提议阻止已转派出去的旧 run 把新负责人的任务关闭，仍 OPEN，不能说整条所有权链已修复。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；更新为恢复治理持续增强，但仍存在开放的完成权问题和部署验收缺口。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/19181" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/paperclipai/paperclip/pull/19184" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/paperclipai/paperclip/pull/19038" target="_blank" rel="noreferrer">3</a> · <a href="https://github.com/paperclipai/paperclip/pull/19186" target="_blank" rel="noreferrer">4</a></p><h3 id="o15-paperclip-runner-私有-park-claim-retire-协议仅合入传输基础" tabindex="-1">O15. Paperclip：Runner 私有 park/claim/retire 协议仅合入传输基础 <a class="header-anchor" href="#o15-paperclip-runner-私有-park-claim-retire-协议仅合入传输基础" aria-label="Permalink to &quot;O15. Paperclip：Runner 私有 park/claim/retire 协议仅合入传输基础&quot;">​</a></h3><p><strong>#19129 MERGED master · 2026-11-04 23:56 UTC</strong></p><p>Unix stream 使用有界 JSON frame、精确 Runner/lease/run/session/turn/item 绑定、请求 ID 重试缓存和冲突检测，并让凭据不继承到 provider 子进程。当前模块没有接入 Runner 启动，不执行 park/claim/retire，也不能证明 VM 可休眠或跨进程死亡恢复。这是可比较的控制消息实现，但语义属于 host/Runtime 生命周期，不是 FCoP 工件协调协议的同层竞品。</p><p><strong>竞品判断：</strong> 学习价值中高；竞争风险暂不因休眠能力上调；雷达标为协议基础已合入、生命周期能力未交付。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/19129" target="_blank" rel="noreferrer">1</a></p><h3 id="o16-paradev-从-elv2-转为-mit-2-0-4-2-0-5-正式发行" tabindex="-1">O16. Paradev：从 ELv2 转为 MIT，2.0.4/2.0.5 正式发行 <a class="header-anchor" href="#o16-paradev-从-elv2-转为-mit-2-0-4-2-0-5-正式发行" aria-label="Permalink to &quot;O16. Paradev：从 ELv2 转为 MIT，2.0.4/2.0.5 正式发行&quot;">​</a></h3><p><strong>#9356 MERGED Nov 4 19:12 UTC; desktop-v2.0.4/.5 RELEASED stable Nov 4–5; LICENSE.md verified</strong></p><p>Superset 原项目的 canonical 仓库已核验为 ParadevAI/Paradev；主程序从 ELv2 改 MIT，SDK 从 Apache-2.0 改 MIT，官网 11 月 4 日公告与 LICENSE.md 一致。允许商业使用/修改仍须保留许可声明，不等于托管服务免费；自有云 Linux host 的终端流量仍经厂商 relay。2.0.4 的清单包含昨天的人/Dev actor 和归档自动化机制，现为发行进展。Pro 不再展示 cloud 小时，但 #9365 明确实际额度和计费未改，不能写成已取消权益。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险上调：许可和自托管门槛下降。雷达更新为 MIT 开源，仍保留 relay、平台和企业能力边界。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/9356" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.4" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.5" target="_blank" rel="noreferrer">3</a> · <a href="https://paradev.com/blog/paradev-is-now-mit" target="_blank" rel="noreferrer">4</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9365" target="_blank" rel="noreferrer">5</a></p><h3 id="o17-paradev-工作区复用与会话延续独立配置" tabindex="-1">O17. Paradev：工作区复用与会话延续独立配置 <a class="header-anchor" href="#o17-paradev-工作区复用与会话延续独立配置" aria-label="Permalink to &quot;O17. Paradev：工作区复用与会话延续独立配置&quot;">​</a></h3><p><strong>#9377/#9378 MERGED Nov 5 01:46/01:58 UTC; included in desktop-v2.0.5</strong></p><p>自动化可选每次新工作区、首次创建后复用、手选工作区；共享工作区时再选 fresh/continue 会话。自动固定首次创建的 host/workspace，并处理旧客户端回写和删除后重建。上游仍未完成运行中桌面/云全流程人工 QA；尤其 PR 触发器若复用工作区，后续 PR 可能继续使用首个 PR checkout，作者明确建议此类自动化选新工作区。这是数字员工持续履职与任务隔离的实际取舍。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险中高；增加持续工作环境研究，不把复用自动等同于正确隔离。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/9377" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9378" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.5" target="_blank" rel="noreferrer">3</a></p><h3 id="o18-orca-1-4-249-不确定投递保留原消息-临时审批不落成永久授权" tabindex="-1">O18. Orca 1.4.249：不确定投递保留原消息，临时审批不落成永久授权 <a class="header-anchor" href="#o18-orca-1-4-249-不确定投递保留原消息-临时审批不落成永久授权" aria-label="Permalink to &quot;O18. Orca 1.4.249：不确定投递保留原消息，临时审批不落成永久授权&quot;">​</a></h3><p><strong>v1.4.249 RELEASED stable · Nov 4 23:53 UTC; #32267/#37895 MERGED Nov 4; #37895 release inclusion not independently pinned</strong></p><p>投递超时后保留原消息一次，不自动重发或退回输入框；队列的编辑、附件、顺序和 held 状态跨 Stop/restart 保存。临时会话批准的映射修复把 destination 改为 session，避免写入项目永久规则；既有误写规则不会自动清除。新发行再次禁用实验 orchestration 面板，移动功能还需 Mobile 0.0.64；插件替换重复动作和聊天存储增长仍列已知问题。不能把发版当协作治理成熟证明。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；消息可靠性增强，编排面板成熟度下调，保留重复副作用风险。</p><p>原始来源：<a href="https://github.com/stablyai/orca/releases/tag/v1.4.249" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/stablyai/orca/pull/32267" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/stablyai/orca/pull/37895" target="_blank" rel="noreferrer">3</a></p><h3 id="o19-orca-空闲主会话不等于后台员工已停止" tabindex="-1">O19. Orca：空闲主会话不等于后台员工已停止 <a class="header-anchor" href="#o19-orca-空闲主会话不等于后台员工已停止" aria-label="Permalink to &quot;O19. Orca：空闲主会话不等于后台员工已停止&quot;">​</a></h3><p><strong>#38207/#38257 MERGED Nov 5 03:47/01:48 UTC; #38379 OPEN; later than 1.4.249</strong></p><p>Pi 活性 registry 统计排队/运行后代、未投递结果和待唤醒 turn；只有当前实例在五秒内明确回答 idle 才允许回收，无答复宁可保留会话，代价是故障桥可能一直占资源。另一修复移除 128 个开放条目导致长 turn 被误停的硬限制，仍保留字节预算。Claude 重启后后台唤醒 #38379 仍 OPEN 且依赖草稿恢复修复，不能宣称所有 provider 均已解决。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险中高；增加后台履职生命周期机制，但仅按已合入 provider 范围判断。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/38207" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/stablyai/orca/pull/38257" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/stablyai/orca/pull/38379" target="_blank" rel="noreferrer">3</a></p><h3 id="o20-orkas-正式版-周期排班、队列恢复与双副本保留" tabindex="-1">O20. Orkas 正式版：周期排班、队列恢复与双副本保留 <a class="header-anchor" href="#o20-orkas-正式版-周期排班、队列恢复与双副本保留" aria-label="Permalink to &quot;O20. Orkas 正式版：周期排班、队列恢复与双副本保留&quot;">​</a></h3><p><strong>v2026.11.4 RELEASED stable · Nov 4 15:59 UTC; #176 MERGED</strong></p><p>新增多星期/多月日排班选择，恢复队列输入、附件和中断会话；Library 迁移遇并发修改/部分删除时保留两份可恢复数据。合入说明仍记录 Commander/OfficeWorker 初始开销超过 20k token 门槛、严格 GPU 日志案例失败、Windows/Linux 真机和全应用性能验收不全；不得用发版抹掉这些缺口。昨日 #174 的授权/执行文字误报仍是 OPEN 的报告者线索，未证明真实泄露或执行。</p><p><strong>竞品判断：</strong> 学习价值中高；竞争风险中高；提高排班和恢复交付关注度，跨平台生产成熟度不升级。</p><p>原始来源：<a href="https://github.com/Orkas-AI/Orkas/releases/tag/v2026.11.4" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/176" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/Orkas-AI/Orkas/issues/174" target="_blank" rel="noreferrer">3</a></p><h3 id="o21-staffdeck-个人-mcp-oauth-与按需能力发现仍为草稿" tabindex="-1">O21. StaffDeck：个人 MCP OAuth 与按需能力发现仍为草稿 <a class="header-anchor" href="#o21-staffdeck-个人-mcp-oauth-与按需能力发现仍为草稿" aria-label="Permalink to &quot;O21. StaffDeck：个人 MCP OAuth 与按需能力发现仍为草稿&quot;">​</a></h3><p><strong>#304/#305 OPEN DRAFT · created 2026-11-04 09:49/09:56 UTC; author duhu2000</strong></p><p>提案按 tenant/user/server 隔离加密凭据，使用 DCR、PKCE、一次性 state；调用时解析当前聊天用户，资源地址变化阻止旧令牌复用。企查查连接复用 capability_search/describe，不把完整 schema 目录灌入模型。刷新锁限单进程，提前 401 要重授权且不自动重放业务动作。所有目录/短信 OAuth 验证目前是 mock，未完成正式包和真实角色 UI 验收；不是官方已发布能力，也不是 186 个生产工具已验证。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险暂不因草稿上调；列为身份隔离与企业工具接入研究线索，仓库 AGPL-3.0 元数据已核验。</p><p>原始来源：<a href="https://github.com/OpenBMB/StaffDeck/pull/304" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/OpenBMB/StaffDeck/pull/305" target="_blank" rel="noreferrer">2</a></p><h3 id="o22-anthropic-官方-cookbook-用完成会话蒸馏可追溯的文件记忆" tabindex="-1">O22. Anthropic 官方 cookbook：用完成会话蒸馏可追溯的文件记忆 <a class="header-anchor" href="#o22-anthropic-官方-cookbook-用完成会话蒸馏可追溯的文件记忆" aria-label="Permalink to &quot;O22. Anthropic 官方 cookbook：用完成会话蒸馏可追溯的文件记忆&quot;">​</a></h3><p><strong>#959 MERGED main · 2026-11-04 19:06 UTC; notebook and helpers read</strong></p><p>lead 编排每份 transcript 的 analyzer，全部完成后 organizer 整理索引；原始会话只读，蒸馏阶段写记忆，业务会话只读挂载，事实注明过期/替代关系。它提供 notebook 和 nightly 脚本，要求 Python ≥3.11、SDK 2.x 与 Managed Agents beta 访问，不是纯本地免费方案。默认夜间原地更新没有人工审阅，恶意 transcript 仍可能污染记忆；长期未完成会话可能被时间窗口漏掉。上游成本/事实保留测试是作者结果，本地未运行。</p><p>原始来源：<a href="https://github.com/anthropics/claude-cookbooks/pull/959" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/anthropics/claude-cookbooks/blob/main/managed_agents/CMA_dreaming_with_a_dynamic_workflow.ipynb" target="_blank" rel="noreferrer">2</a></p><h3 id="o23-dspy-结构化历史-react-成为-3-5-主实现" tabindex="-1">O23. DSPy：结构化历史 ReAct 成为 3.5 主实现 <a class="header-anchor" href="#o23-dspy-结构化历史-react-成为-3-5-主实现" aria-label="Permalink to &quot;O23. DSPy：结构化历史 ReAct 成为 3.5 主实现&quot;">​</a></h3><p><strong>#10795/#10800 MERGED main · Nov 4; stable 3.5 release unverified</strong></p><p>typed submit 保留输出约束，强制提交失败会抛错而非给不完整结果；支持结构化 history 和同 turn 多个顺序工具调用。旧 trajectory/extractor 优化状态须迁移并重新编译，ReActV2 仅保留弃用别名到 3.6，TwoStepAdapter 在 3.5 弃用。作者示例 2→1、4→2 次调用只是执行形态对照，不是准确率/延迟 benchmark。适合观察可验证的结果提交与历史结构，不能当无成本升级。</p><p>原始来源：<a href="https://github.com/stanfordnlp/dspy/pull/10795" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10800" target="_blank" rel="noreferrer">2</a></p><h3 id="o24-semantic-kernel-业务数据修改须明确映射-网络检查绑定真实连接" tabindex="-1">O24. Semantic Kernel：业务数据修改须明确映射，网络检查绑定真实连接 <a class="header-anchor" href="#o24-semantic-kernel-业务数据修改须明确映射-网络检查绑定真实连接" aria-label="Permalink to &quot;O24. Semantic Kernel：业务数据修改须明确映射，网络检查绑定真实连接&quot;">​</a></h3><p><strong>#14718/#14719 MERGED main · Nov 4 15:35 UTC; Python #14724 OPEN Nov 5</strong></p><p>结构化数据插件默认 query-only，insert/update 用独立请求类型和显式映射，update/delete 由应用约束目标实体；旧直接实体修改重载 fail closed。HTTP 插件把已验证地址绑定到实际连接并保留 TLS 主机名，不受控自定义客户端无法保证时拒绝。另开放提案修复模型截断、尚未写参数却以工具默认值执行的问题，显式 {} 与“根本没写参数”必须区分。后者未合入，不能写成现有防护。</p><p>原始来源：<a href="https://github.com/microsoft/semantic-kernel/pull/14718" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/microsoft/semantic-kernel/pull/14719" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/microsoft/semantic-kernel/pull/14724" target="_blank" rel="noreferrer">3</a></p><h3 id="o25-langfuse-读审计扩大-同时出现提示大小限制的回滚事故" tabindex="-1">O25. Langfuse：读审计扩大，同时出现提示大小限制的回滚事故 <a class="header-anchor" href="#o25-langfuse-读审计扩大-同时出现提示大小限制的回滚事故" aria-label="Permalink to &quot;O25. Langfuse：读审计扩大，同时出现提示大小限制的回滚事故&quot;">​</a></h3><p><strong>v4.75.0 RELEASED Nov 4 09:26 UTC; #19625 MERGED 15:33; #19742 revert MERGED 21:21 (both later than release)</strong></p><p>4.75 加入 Codex skill 资源加载 trace、本人 gateway 用量查看及采集限流 503/Retry-After。之后 #19625 为 28 个 v4 读取过程增加资源引用/拒绝审计；成功读取在 staging 写失败时阻断，拒绝仍返回 401/403，受企业许可/开关与路由选择约束，尚有未覆盖读路径。4.75 内的 500 万字符 prompt cap 误伤既有组合 prompt，并在读取时 409；官方记录 EU Cloud 故障，main 已回滚，但放大风险仍未解决。不能把之后的审计或回滚说成已包含在 4.75 包中。</p><p>原始来源：<a href="https://github.com/langfuse/langfuse/releases/tag/v4.75.0" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/langfuse/langfuse/pull/19625" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/langfuse/langfuse/pull/19742" target="_blank" rel="noreferrer">3</a></p><h3 id="o26-phoenix-实验身份记录更多设置-但脱敏有明确取舍" tabindex="-1">O26. Phoenix：实验身份记录更多设置，但脱敏有明确取舍 <a class="header-anchor" href="#o26-phoenix-实验身份记录更多设置-但脱敏有明确取舍" aria-label="Permalink to &quot;O26. Phoenix：实验身份记录更多设置，但脱敏有明确取舍&quot;">​</a></h3><p><strong>arize-phoenix-client-v3.7.0 RELEASED Nov 5 03:07 UTC; JS client 7.18.1 RELEASED Nov 4</strong></p><p>Harbor 实验元数据记录模型参数、Agent kwargs、超时、轨迹恢复和环境变量名，以区分同模型不同运行设置；不存环境变量值，URL 凭据脱敏。但按敏感键名过滤无法保证 neutral-name 下的密钥不泄漏，作者明确保留这个取舍；不是完整防泄漏证明。JS 客户端同时保留失败实验 task span 的错误状态。更适合研究实验可重建性与最小必要记录，而非仅比较模型名字。</p><p>原始来源：<a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-client-v3.7.0" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/Arize-ai/phoenix/pull/17457" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/Arize-ai/phoenix/releases/tag/@arizeai/phoenix-client@7.18.1" target="_blank" rel="noreferrer">3</a></p><h3 id="o27-langchain-嵌套代码工具复用同一审批-中间件的原型" tabindex="-1">O27. LangChain：嵌套代码工具复用同一审批/中间件的原型 <a class="header-anchor" href="#o27-langchain-嵌套代码工具复用同一审批-中间件的原型" aria-label="Permalink to &quot;O27. LangChain：嵌套代码工具复用同一审批/中间件的原型&quot;">​</a></h3><p><strong>#41702 OPEN DRAFT · created Nov 5 04:38 UTC; #41689 MERGED Nov 4</strong></p><p>get_tool_executor 原型让程序化嵌套工具经过现有 ToolNode 和全套 middleware，保留已完成结果跨 approval/resume，避免审批恢复重复副作用。仅支持返回 message 的工具，拒绝批量 HITL 与 Command；QuickJS heap、每 turn 工具过滤、文件 read-your-writes 仍是独立设计门槛。未合入、未迁移 Deep Agents。另已合入的 ModelRefusalMiddleware 默认不记录 trace 输入 payload，稳定发行包含情况未核实。</p><p>原始来源：<a href="https://github.com/langchain-ai/langchain/pull/41702" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/langchain-ai/langchain/pull/41689" target="_blank" rel="noreferrer">2</a></p><h3 id="o28-browser-use-1-0-草稿-从固定动作转向持久-python-repl" tabindex="-1">O28. Browser Use 1.0 草稿：从固定动作转向持久 Python REPL <a class="header-anchor" href="#o28-browser-use-1-0-草稿-从固定动作转向持久-python-repl" aria-label="Permalink to &quot;O28. Browser Use 1.0 草稿：从固定动作转向持久 Python REPL&quot;">​</a></h3><p><strong>#6314 OPEN DRAFT targeting v1 · created Nov 5 04:29 UTC; main remains 0.x</strong></p><p>Pydantic AI + browser-harness/CDP 的新架构默认厂商 gateway 与云浏览器，可选本地 Chrome；worker 环境变量 allowlist、type_secret 和输出脱敏试图限制密钥暴露。但作者明确 REPL 不是 sandbox，代码可读本地文件；旧参数、旧 MCP 工具和集成有迁移破坏。live gateway、真实云浏览器和公共 benchmark 尚未跑通/执行，Windows 尚待首轮 CI。只能列前沿观察，不能写成 1.0 已发布或安全性已验证。</p><p>原始来源：<a href="https://github.com/browser-use/browser-use/pull/6314" target="_blank" rel="noreferrer">1</a></p><h3 id="o29-gemini-与-copilot-取消、恢复、配置失败的精确语义" tabindex="-1">O29. Gemini 与 Copilot：取消、恢复、配置失败的精确语义 <a class="header-anchor" href="#o29-gemini-与-copilot-取消、恢复、配置失败的精确语义" aria-label="Permalink to &quot;O29. Gemini 与 Copilot：取消、恢复、配置失败的精确语义&quot;">​</a></h3><p><strong>Gemini v0.67.0 stable/v0.68.0-preview.0 prerelease RELEASED Nov 4; Copilot v1.0.106-9 prerelease RELEASED Nov 4</strong></p><p>Gemini 稳定 0.67 包含取消后阻止非交互工具继续执行和 MCP 权限请求元数据；0.68 preview 才包含此前的 ACP history replay 等待、SubagentStop hook 合并，以及扩展安装串行化。Copilot -9 的 ACP cancel 仅停当前 turn，后台任务/命令继续；配置类型错误给出警告，悬空 symlink 的工作区外访问先请求权限。不同产品 Stop 语义并不一致，必须在适配层验证，不能统一承诺“取消全部”。</p><p>原始来源：<a href="https://github.com/google-gemini/gemini-cli/releases/tag/v0.67.0" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google-gemini/gemini-cli/releases/tag/v0.68.0-preview.0" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-9" target="_blank" rel="noreferrer">3</a></p><h3 id="o30-openhands-sdk-子-agent-凭据上下文与插件缺失可见性" tabindex="-1">O30. OpenHands SDK：子 Agent 凭据上下文与插件缺失可见性 <a class="header-anchor" href="#o30-openhands-sdk-子-agent-凭据上下文与插件缺失可见性" aria-label="Permalink to &quot;O30. OpenHands SDK：子 Agent 凭据上下文与插件缺失可见性&quot;">​</a></h3><p><strong>#6461/#6460 MERGED main · Nov 4 19:36/15:32 UTC; release inclusion unverified</strong></p><p>具名 LLM profile 的子 Agent 注册现在传 owning conversation cipher，避免把静态加密密文当 API key 发给 provider；已有共享 registry 的名字可复用，但子 conversation 再发现新 Agent 的嵌套路径仍有限制。自动加载 marketplace/plugin 失败会向用户发脱敏错误事件，保持非致命，不再只写 warning 让技能/子 Agent 静默缺失。没有因此证明 fallback 或所有嵌套委派路径已修复。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6461" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6460" target="_blank" rel="noreferrer">2</a></p><h3 id="o31-beads-1-3-4-昨日候选修复进入稳定版-恢复风险仍需保留" tabindex="-1">O31. Beads 1.3.4：昨日候选修复进入稳定版，恢复风险仍需保留 <a class="header-anchor" href="#o31-beads-1-3-4-昨日候选修复进入稳定版-恢复风险仍需保留" aria-label="Permalink to &quot;O31. Beads 1.3.4：昨日候选修复进入稳定版，恢复风险仍需保留&quot;">​</a></h3><p><strong>v1.3.4 RELEASED stable · 2026-11-04 09:22 UTC; #8123 MERGED main later</strong></p><p>1.3.4 仅在 1.3.3 上恢复读取 rig .beads/.env 的 GT_ROOT，修正已发行 Gas City 对 bd 失败的误报；多平台二进制已发布。旧版本升级仍需遵守 migration 0062 后不运行 compact/flatten 的警告；events restore 和 server reset-data 重做不在该版本。之后 main 又限制从该环境文件得到的 GT_ROOT 不可用于写 formula，不能当成已进入 1.3.4。状态进展有价值，但不是新的完整恢复方案。</p><p><strong>竞品判断：</strong> 学习价值中高；竞争风险维持中高；修复已稳定交付，升级与数据恢复风险不下调。</p><p>原始来源：<a href="https://github.com/gastownhall/beads/releases/tag/v1.3.4" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/gastownhall/beads/pull/8123" target="_blank" rel="noreferrer">2</a></p><h3 id="c1-历史协议补查-不计本轮新增" tabindex="-1">C1. 历史协议补查，不计本轮新增 <a class="header-anchor" href="#c1-历史协议补查-不计本轮新增" aria-label="Permalink to &quot;C1. 历史协议补查，不计本轮新增&quot;">​</a></h3><p>MCP <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2848" target="_blank" rel="noreferrer">异步工具审批 #2848</a> 与 <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3415" target="_blank" rel="noreferrer">Events #3415</a> 均 OPEN，参考实现/评审仍有缺口。已核实最后实质提交分别为 8 月 26 日、10 月 27 日；今天的 updated_at 不能冒充今天新增。前者可研究断线审批、执行前重新授权和 outcome-unknown，后者可研究游标重放和事件触发。仅为历史资料/协议比较候选，不代表已采纳标准、真实互操作或 FCoP 同层替代。</p><h2 id="第二层-研究分析" tabindex="-1">第二层：研究分析 <a class="header-anchor" href="#第二层-研究分析" aria-label="Permalink to &quot;第二层：研究分析&quot;">​</a></h2><h3 id="a1-企业治理的授权单位-需要细到主体、资源、动作与当前问题" tabindex="-1">A1. 企业治理的授权单位，需要细到主体、资源、动作与当前问题 <a class="header-anchor" href="#a1-企业治理的授权单位-需要细到主体、资源、动作与当前问题" aria-label="Permalink to &quot;A1. 企业治理的授权单位，需要细到主体、资源、动作与当前问题&quot;">​</a></h3><p><strong>依据：O2、O6、O10、O18、O21、O24</strong></p><p>已有证据：过期 interrupt、MCP owner 环境、被撤销凭据、会话授权误持久化和显式实体映射，都说明一次登录或一份角色说明不能独自表达执行权。待验证推断：CodeFlowMu 可研究把岗位/委派依据、人工决定版本、当前执行主体和资源范围关联检查；目前未证明本地存在对应缺陷。实验候选 E1：同一任务经转派、撤权、第二次审批和工具环境切换后，重放旧答复/旧凭据，观察实际动作是否仍被接受。交互议题：LangGraph 的旧 ID 兼容回退与应用层 approval revision 如何共同约束？</p><h3 id="a2-协作协议研究应比较消息语义与证据契约-并区分-runtime" tabindex="-1">A2. 协作协议研究应比较消息语义与证据契约，并区分 Runtime <a class="header-anchor" href="#a2-协作协议研究应比较消息语义与证据契约-并区分-runtime" aria-label="Permalink to &quot;A2. 协作协议研究应比较消息语义与证据契约，并区分 Runtime&quot;">​</a></h3><p><strong>依据：O1、O5、O7、O8、O12、O15、O17、O27</strong></p><p>已有证据：AG2 区分观察与执行，Codex 区分记录与模型采样，A2A 区分私有持久状态与公开 Task 投影，MCP Apps 以安全属性约束宿主而不固定 iframe 结构。待验证推断：与 FCoP 比较时，应问任务/工件/事件 ID、状态变更、交付确认、证据引用和互操作如何表达；Runner park/claim、工作区复用和进程回收属于 CodeFlowMu Runtime/适配层。不能仅因都用文件或消息，就说是同层替代。资料候选 C1 的 MCP 异步审批/Events 值得补查，但实质提交早于窗口，不计新增。</p><h3 id="a3-持续履职需要-可继续-与-可完成-的不同证据" tabindex="-1">A3. 持续履职需要“可继续”与“可完成”的不同证据 <a class="header-anchor" href="#a3-持续履职需要-可继续-与-可完成-的不同证据" aria-label="Permalink to &quot;A3. 持续履职需要“可继续”与“可完成”的不同证据&quot;">​</a></h3><p><strong>依据：O3、O13、O14、O19、O20、O29、O30、O31</strong></p><p>已有证据：Paperclip 的交付物复核、文件恢复 hold、OpenAI 的 unknown effect、Orca 的 worker 活性及不同 CLI 的 cancel 范围，分别处理不同生命周期事实。重试成功、会话还活着、文件已救回，都不能自动证明任务已完成或可以重放副作用。待验证推断：数字员工产品可把待输入、后台仍工作、结果未知、恢复阻断、待独立验收分别呈现。E2 候选：在副作用后/回执前、交付后/状态提交前、转派后/旧 run 结束前中断；核对外部效果、凭据和当前负责人。互动议题：Paperclip #19186 与 #19130 的所有权/发布检查如何在同一提交边界组合？</p><h3 id="a4-数字员工的记忆应有来源、修订和写入职责" tabindex="-1">A4. 数字员工的记忆应有来源、修订和写入职责 <a class="header-anchor" href="#a4-数字员工的记忆应有来源、修订和写入职责" aria-label="Permalink to &quot;A4. 数字员工的记忆应有来源、修订和写入职责&quot;">​</a></h3><p><strong>依据：O1、O6、O9、O22、O23、O26</strong></p><p>已有证据：Anthropic 用业务只读/蒸馏写入分工和文件索引保留经验，仍承认夜间污染与未完成会话遗漏；AG2 共享作用域和 ADK 并发修复说明共享记忆不等于无冲突；Codex 记忆整理只授予专用写根。待验证推断：岗位经验、任务状态、个人偏好和组织规则可分别研究生命周期，不将它们混成一个可任意更新的库。E3 候选：合成过期 SOP、恶意工具输出、跨用户样本及中断会话，检查事实替代、来源保留、审核前生效和回滚。此处是实验设计，尚未运行。</p><h3 id="a5-审计和评测先保证记录的含义-再讨论数量与分数" tabindex="-1">A5. 审计和评测先保证记录的含义，再讨论数量与分数 <a class="header-anchor" href="#a5-审计和评测先保证记录的含义-再讨论数量与分数" aria-label="Permalink to &quot;A5. 审计和评测先保证记录的含义，再讨论数量与分数&quot;">​</a></h3><p><strong>依据：O4、O11、O24、O25、O26、O27</strong></p><p>已有证据：ADK 不完整轨迹不能进入就绪评测，Phoenix 记录模型之外的运行设置，Langfuse 给返回数据附资源审计，Semantic Kernel 区分空参数与未生成参数。新增 tracing 并不证明完整审计：best-effort 会丢失、脱敏规则有漏项、EE 和路由有覆盖边界。待验证推断：验收可同时检查来源、完整度、当前授权、失败/未知状态与可重建配置，不能只用模型“通过”文本。Langfuse 的读时 cap 回滚也说明保护措施必须验证已有工作负载和发布迁移。</p><h3 id="a6-竞品重估看可运行交付、许可和治理代价" tabindex="-1">A6. 竞品重估看可运行交付、许可和治理代价 <a class="header-anchor" href="#a6-竞品重估看可运行交付、许可和治理代价" aria-label="Permalink to &quot;A6. 竞品重估看可运行交付、许可和治理代价&quot;">​</a></h3><p><strong>依据：O3、O16、O17、O18、O19、O20、O21、O22、O28</strong></p><p>已有证据：Paradev MIT 改变可学习/二次使用门槛，是本轮最明确的竞争判断更新；AG2 等稳定发行可列体验候选。Orca 面板再次禁用、Orkas 验收缺口、StaffDeck 草稿和 Browser Use v1 重构则限制成熟度判断。待验证推断：开源产品可作为“机制样本”或“完整体验样本”，但 CodeFlowMu 的数字员工交付还要比较岗位、协作、验收、长期运行和企业边界，不能只比并行窗口。体验候选按下文前提执行，尚无本地实验/文章/开发评审；不会从日报自动派工。</p><h2 id="分类处置与体验前提" tabindex="-1">分类处置与体验前提 <a class="header-anchor" href="#分类处置与体验前提" aria-label="Permalink to &quot;分类处置与体验前提&quot;">​</a></h2><ul><li>X1【体验候选】AG2 1.3（Apache-2.0）：独立 Python ≥3.11 环境，先跑委派事件/作用域样例，再研究接入成本与 1.4 迁移；模型调用需要相应凭据/费用。</li><li>X2【体验候选】LangGraph 1.2.20（MIT）：本地 checkpoint 的过期答复/多问题恢复；严格键仍私有，远端路径另验，不先承诺企业审批系统已具备。</li><li>X3【体验候选】Paradev 2.0.5（MIT）：沿官方开发或发行路径体验自动化复用；桌面以 macOS 为主、Linux 实验发行，Windows 不列已交付；自有云 Linux host 仍有 relay 和账号依赖，托管能力不等于免费。</li><li>X4【体验候选】Anthropic dreaming cookbook（仓库 MIT）：Python ≥3.11、Managed Agents beta 权限和付费 API，先用合成 transcript/新 memory store；默认夜间写入、数据保留与审核边界必须核对。</li><li>X5【持续观察】OpenAI 原生 worker/SessionStore 与 Browser Use v1：前者预览分支/未合入存储提案，后者 v1 草稿；待固定可安装包、平台和接口后再决定体验，当前不宣称可直接替换现有 Runtime。</li></ul><p>本轮：31 组事实、6 组分析、4 个体验候选、3 个实验设计候选 E1–E3；<strong>已完成实验 0、文章 0、正式开发评审 0、外部评论 0</strong>。互动仅列 A1/A3 的具体技术议题，尚未发评论。其他观察分别用于持续观察或资料留存，不自动派工。</p><h2 id="双源核查、覆盖缺口与发布边界" tabindex="-1">双源核查、覆盖缺口与发布边界 <a class="header-anchor" href="#双源核查、覆盖缺口与发布边界" aria-label="Permalink to &quot;双源核查、覆盖缺口与发布边界&quot;">​</a></h2><p>最新 main Registry SHA <code>8d97df65269aa2b4accd1366d1b71319f99c6efd</code>，实有 <strong>47 位研究者、88 个仓库目标</strong>，未改 Registry。人物是研究主体，仓库是证据入口；始终使用“赵越”。六位治理研究者的仓库关系沿用已核验边界，bulbasaur-skill-cli 不称 AGENTSAFE 官方 Artifact。赵越相关本轮仅有配额显示小改动，未核实新论文/benchmark/核心审计机制，未凑数报道。</p><ul><li>GitHub：检查 830 条 commit、173 条 Issue/PR 列表记录、192 条 Release 记录并定向回读关键 PR/规范/许可/notebook。Paperclip 134 条、两页完整；Orca 四页 400 条仍未翻完，不推进基线；TSA 无法访问，不能说无变化。其余 86 个目标仅对完成的 commit 查询推进至起点。</li><li>Issue/PR 每仓最新 5 条、Release 最新 3 条属于有界检查，历史完整覆盖基线不推进；未遍历全部 Issues/Discussions/Roadmap 和作者回复。PR 列表 CLOSED 经 pull detail 区分 MERGED 与未合入，未将自动关闭的 MCP Python SDK PR 当修复发布。</li><li>另一来源类型：实际打开 Cursor 官方 changelog/工程 notes、赵越主页/审计主页、LangChain 博客及 Paradev 官方公告。Paradev 11 月 4 日 MIT 公告与代码许可相互核对；Cursor 目前可读的最新相关日期仍在 10 月；LangChain 11 月 3 日文章早于当前窗口，仅留历史线索。</li><li>X：定向检索 Harrison Chase、Chi Wang、赵越相关公开动态，未取得可确认日期的当轮原帖；镜像和检索无结果均不等于穷尽 47 人本人/回复/线程。GitHub 工程事实可独立成立，不将两个 GitHub 链接伪称两类来源。</li><li>主作者参与：PR 可见 cryppadotta、markstuart-oai、Kitenite 等作者直接提交，但账户身份与角色以可验证来源为限，第三方草稿不视为维护者承诺。许可仅核验仓库元数据及 Paradev 正文，不替代完整依赖许可检查。</li><li>本地查询超时已重试恢复；仍保留 Orca 分页与 TSA 访问缺口。查询记录、事件 ID/SHA/状态、去重结果与发布回执保存于本地监测目录；只推进实际完整成功来源。</li></ul><p>日报独立于 Research Runtime 生命周期。本轮源文件仅限两种语言当日日报及两个索引；沿现有站点实现构建/发布并保留公开快照、布局和固定入口。上线结果须由对应新提交的 Pages 成功及在线索引/完整日报点击验收确认，在聊天和本地回执报告，不能用本源文件自行证明。</p><h2 id="当日后续研究成果" tabindex="-1">当日后续研究成果 <a class="header-anchor" href="#当日后续研究成果" aria-label="Permalink to &quot;当日后续研究成果&quot;">​</a></h2><p>上文的“实验 0、文章 0”是 <strong>13:43:53 巡检完成时的快照</strong>。其后按 X1–X4 实际运行固定版本的局部入口，将结果回写到 A1 授权、A2 多 Agent 协作、A4 记忆治理和 A6 竞品判断。完成 4 个上游代码探针及 CodeFlowMu 1 个执行契约探针；CodeFlowMu 六组定向测试共 77 项通过。Paradev 桌面和 Anthropic 付费云端蒸馏未做端到端体验，不计入通过。</p><p>成果：<a href="/joinwell52/zh/research/2026-11-05-what-an-agent-inherits">中文文章《换一个 AI 接手，哪些东西可以带走？》</a> · <a href="/joinwell52/en/research/2026-11-05-what-an-agent-inherits">English</a> · <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-05-handoff-boundaries/00-report.md" target="_blank" rel="noreferrer">公开中文证据</a> · <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-05-handoff-boundaries/00-report.en.md" target="_blank" rel="noreferrer">English evidence</a>。本轮未证实 CodeFlowMu 对应故障，正式开发评审 0 项；外部评论 0 条。A3 交付恢复和 A5 审计评测仍是日档研究线索，未被这四个探针覆盖。</p>',170)])])}const u=a(n,[["render",l]]);export{d as __pageData,u as default};
